+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/** The name and status criteria understood by the customer backend. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Returns whether this filter accepts the given customer. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+
+        String firstName = searchable(customer.firstName());
+        String lastName = searchable(customer.lastName());
+        return nameTerms().stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private List<String> nameTerms() {
+        return WHITESPACE.splitAsStream(searchable(name))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    private static String searchable(String value) {
+        return MARKS.matcher(Normalizer.normalize(value, Normalizer.Form.NFD))
+                .replaceAll("")
+                .toLowerCase(Locale.ROOT);
+    }
+}
