+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.Application;
+import com.example.customers.domain.QueryLog;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Test
+    void urlHydrationAndDebouncedUrlWritingWorkInABrowser() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction("() => document.querySelector('vaadin-text-field')?.value === 'vir'");
+
+        assertEquals("vir", page.locator("vaadin-text-field input").inputValue());
+        MultiSelectComboBoxElement status =
+                MultiSelectComboBoxElement.getByLabel(page, "Status");
+        status.assertSelectedItems("ACTIVE", "CLOSED");
+        GridElement.get(page).assertRowCount(10);
+        assertTrue(page.getByText("Showing 10 of 500").isVisible());
+
+        page.navigate(getUrl());
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+        queryLog.clear();
+        int historyLength = ((Number) page.evaluate("history.length")).intValue();
+
+        Locator name = page.locator("vaadin-text-field input");
+        name.pressSequentially("josephine");
+        page.waitForFunction("() => location.search === '?name=josephine'");
+        GridElement.get(page).assertRowCount(12);
+
+        assertEquals(historyLength,
+                ((Number) page.evaluate("history.length")).intValue());
+        assertEquals(1, queryLog.countQueries().size(),
+                "Typing one name should result in one debounced count query");
+        assertTrue(queryLog.pageQueries().size() <= 1,
+                "Typing one name should result in at most one page query");
+
+        name.clear();
+        page.waitForFunction("() => location.search === ''");
+        status.selectItems("CLOSED", "ACTIVE");
+        page.waitForTimeout(1000);
+        assertEquals(getUrl() + "?status=ACTIVE,CLOSED", page.url());
+
+        name.pressSequentially("vir");
+        page.waitForFunction(
+                "() => location.search === '?name=vir&status=ACTIVE,CLOSED'");
+    }
+}
